  { id: "fr-fc-c1-01", front: "Poser un lapin à quelqu'un", phonetic: "poh-ZAY uhn lah-PAHN", back: "To stand someone up (fail to show up for a date)", category: "Levels C1 & C2: Fluency & Mastery", example: "Il ne m'a pas prévenu et m'a posé un lapin !" },
  { id: "fr-fc-c1-02", front: "Tomber dans les pommes", phonetic: "tohm-BAY dahn lay POHM", back: "To faint / to pass out", category: "Levels C1 & C2: Fluency & Mastery", example: "Il faisait si étouffant qu'elle est tombée dans les pommes." },
  { id: "fr-fc-c1-03", front: "Avoir le cafard", phonetic: "ah-vwahr luh kah-FAHR", back: "To feel down / depressed / blue", category: "Levels C1 & C2: Fluency & Mastery", example: "Ce temps pluvieux et maussade me donne le cafard." },
  { id: "fr-fc-c1-04", front: "Coûter les yeux de la tête", phonetic: "koo-TAY lay z-yuh duh lah TEHT", back: "To cost an arm and a leg / extremely expensive", category: "Levels C1 & C2: Fluency & Mastery", example: "Ce logement en plein cœur de Paris coûte les yeux de la tête." },
  { id: "fr-fc-c1-05", front: "Donner sa langue au chat", phonetic: "doh-NAY sah lahng oh SHAH", back: "To give up guessing a riddle", category: "Levels C1 & C2: Fluency & Mastery", example: "Je n'ai aucune idée de la réponse, je donne ma langue au chat." },
  { id: "fr-fc-c1-06", front: "Mettre les pieds dans le plat", phonetic: "meh-truh lay pyay dahn luh PLAH", back: "To put one's foot in one's mouth / blunder tactlessly", category: "Levels C1 & C2: Fluency & Mastery", example: "En abordant ce sujet tabou, il a mis les pieds dans le plat." },
  { id: "fr-fc-c1-07", front: "Avoir un poil dans la main", phonetic: "ah-vwahr uhn pwal dahn lah MAHN", back: "To be inherently lazy / averse to work", category: "Levels C1 & C2: Fluency & Mastery", example: "Il refuse d'aider et a visiblement un poil dans la main." },
  { id: "fr-fc-c1-08", front: "Être fleur bleue", phonetic: "eh-truh fluhr BLUH", back: "To be sentimental / romantic / naive", category: "Levels C1 & C2: Fluency & Mastery", example: "Elle adore les comédies romantiques, elle est très fleur bleue." },
  { id: "fr-fc-c1-09", front: "Casser les pieds à quelqu'un", phonetic: "kah-SAY lay pyay", back: "To get on someone's nerves / annoy intensely", category: "Levels C1 & C2: Fluency & Mastery", example: "Arrête de faire ce bruit constant, tu me casses les pieds !" },
  { id: "fr-fc-c1-10", front: "Couper la poire en deux", phonetic: "koo-PAY lah pwahr ahn DUH", back: "To compromise / split the difference", category: "Levels C1 & C2: Fluency & Mastery", example: "Pour régler le litige, coupons la poire en deux." },
  { id: "fr-fc-c1-11", front: "Faire la grasse matinée", phonetic: "fehr lah grahs mah-tee-NAY", back: "To sleep in late in the morning", category: "Levels C1 & C2: Fluency & Mastery", example: "Dimanche est le seul jour où je peux faire la grasse matinée." },
  { id: "fr-fc-c1-12", front: "Se mettre sur son trente-et-un", phonetic: "suh meh-truh sewr sohn trahnt ay UHN", back: "To dress up to the nines / put on one's finest clothes", category: "Levels C1 & C2: Fluency & Mastery", example: "Pour la soirée de gala, tout le monde s'est mis sur son 31." },
  { id: "fr-fc-c1-13", front: "Appeler un chat un chat", phonetic: "ah-play uhn shah uhn SHAH", back: "To call a spade a spade / speak frankly", category: "Levels C1 & C2: Fluency & Mastery", example: "Soyons honnêtes et appelons un chat un chat." },
  { id: "fr-fc-c1-14", front: "Avoir le coup de foudre", phonetic: "ah-vwahr luh koo duh FOOD-ruh", back: "To experience love at first sight", category: "Levels C1 & C2: Fluency & Mastery", example: "Dès leur premier regard échangé, ce fut le coup de foudre." },
  { id: "fr-fc-c1-15", front: "Jeter l'éponge", phonetic: "zhuh-TAY lay-POHNZH", back: "To throw in the towel / give up", category: "Levels C1 & C2: Fluency & Mastery", example: "Malgré les difficultés de l'épreuve, ne jetez jamais l'éponge !" },
  { id: "fr-fc-c1-16", front: "C'est ouf !", phonetic: "say OOF", back: "That's crazy! / incredible! (Verlan of 'fou')", category: "Levels C1 & C2: Fluency & Mastery", example: "Cette performance sur scène était complètement ouf !" },
  { id: "fr-fc-c1-17", front: "C'est chelou", phonetic: "say shuh-LOO", back: "That's sketchy / weird / fishy (Verlan of 'louche')", category: "Levels C1 & C2: Fluency & Mastery", example: "Son comportement soudain est vraiment chelou." },
  { id: "fr-fc-c1-18", front: "Un pote", phonetic: "uhn POHT", back: "A buddy / pal / close friend (colloquial)", category: "Levels C1 & C2: Fluency & Mastery", example: "Je vais boire un verre avec mes vieux potes d'enfance." },
  { id: "fr-fc-c1-19", front: "Le boulot / Le taf", phonetic: "luh boo-LOH / luh TAHF", back: "Job / work (colloquial French)", category: "Levels C1 & C2: Fluency & Mastery", example: "J'ai énormément de taf à terminer avant vendredi." },
  { id: "fr-fc-c1-20", front: "Kiffer", phonetic: "kee-FAY", back: "To love / enjoy thoroughly (popular slang)", category: "Levels C1 & C2: Fluency & Mastery", example: "J'ai trop kiffé ce nouveau film d'animation." },
  { id: "fr-fc-c1-21", front: "Bouquiner", phonetic: "boo-kee-NAY", back: "To read books casually (informal)", category: "Levels C1 & C2: Fluency & Mastery", example: "J'adore bouquiner tranquillement dans mon fauteuil." },
  { id: "fr-fc-c1-22", front: "La bagnole", phonetic: "lah bah-NYOHL", back: "The car (informal / slang)", category: "Levels C1 & C2: Fluency & Mastery", example: "Il a garé sa bagnole au bout de l'impasse." },
  { id: "fr-fc-c1-23", front: "Les fringues", phonetic: "lay FRAHNG", back: "Clothes (informal)", category: "Levels C1 & C2: Fluency & Mastery", example: "Elle déniche toujours de superbes fringues en friperie." },
  { id: "fr-fc-c1-24", front: "Avoir du pain sur la planche", phonetic: "ah-vwahr dew pahn sewr lah PLAHN-shuh", back: "To have a lot on one's plate / tons of work", category: "Levels C1 & C2: Fluency & Mastery", example: "Avec ce nouveau projet d'envergure, nous avons du pain sur la planche." },
  { id: "fr-fc-c1-25", front: "Tirer son épingle du jeu", phonetic: "tee-RAY sohn ay-PANG-gluh", back: "To play one's cards right / come out unscathed", category: "Levels C1 & C2: Fluency & Mastery", example: "Dans ce contexte incertain, l'entreprise a su tirer son épingle du jeu." },
  { id: "fr-fc-c1-26", front: "Faire d'une pierre deux coups", phonetic: "fehr dewn pyehr duh KOO", back: "To kill two birds with one stone", category: "Levels C1 & C2: Fluency & Mastery", example: "En livrant ce colis en chemin, je fais d'une pierre deux coups." },
  { id: "fr-fc-c1-27", front: "Qui vivra verra", phonetic: "kee vee-vrah veh-RAH", back: "Time will tell / we shall see", category: "Levels C1 & C2: Fluency & Mastery", example: "Inutile de spéculer sur l'avenir : qui vivra verra." },
  { id: "fr-fc-c1-28", front: "Il va sans dire que...", phonetic: "eel vah sahn deer KUH", back: "It goes without saying that... (formal discourse)", category: "Levels C1 & C2: Fluency & Mastery", example: "Il va sans dire que la ponctualité est indispensable." },
  { id: "fr-fc-c1-29", front: "Force est de constater que...", phonetic: "fohrs ay duh kohn-stah-TAY", back: "It must be acknowledged that... / clearly evident", category: "Levels C1 & C2: Fluency & Mastery", example: "Force est de constater que les progrès accomplis sont remarquables." },
  { id: "fr-fc-c1-30", front: "Nonobstant", phonetic: "noh-nohb-STAHN", back: "Notwithstanding / despite (literary/legal)", category: "Levels C1 & C2: Fluency & Mastery", example: "Nonobstant les réserves exprimées, le projet fut adopté." },
  { id: "fr-fc-c1-31", front: "Une litote", phonetic: "ewn lee-TOHT", back: "Litotes / understatement (saying less to mean more)", category: "Levels C1 & C2: Fluency & Mastery", example: "Dire 'ce n'est pas mauvais' pour louer un plat d'exception." },
  { id: "fr-fc-c1-32", front: "Un euphémisme", phonetic: "uhn nuh-fay-MEEZ-muh", back: "Euphemism (softening harsh reality)", category: "Levels C1 & C2: Fluency & Mastery", example: "'Les personnes défavorisées' au lieu de 'les pauvres'." },
  { id: "fr-fc-c1-33", front: "La synthèse de documents", phonetic: "lah sahn-TEHZ duh doh-kew-MAHN", back: "Comparative document synthesis (C1/C2 official exam task)", category: "Levels C1 & C2: Fluency & Mastery", example: "La synthèse de documents exige rigueur et esprit critique." },
  { id: "fr-fc-c1-34", front: "L'esprit de finesse", phonetic: "leh-spree duh fee-NESS", back: "Subtle discernment / intuitive insight (Pascalian concept)", category: "Levels C1 & C2: Fluency & Mastery", example: "L'esprit de finesse permet de saisir les non-dits et l'humour." },
  { id: "fr-fc-c1-35", front: "Un parti pris", phonetic: "uhn pahr-tee PREE", back: "A conscious stance / bias / artistic angle", category: "Levels C1 & C2: Fluency & Mastery", example: "Le réalisateur a adopté un parti pris résolument minimaliste." },
  { id: "fr-fc-c1-36", front: "L'éloquence", phonetic: "lay-loh-KAHNS", back: "Eloquence / the art of persuasive speaking", category: "Levels C1 & C2: Fluency & Mastery", example: "Son éloquence naturelle captive immédiatement son auditoire." },
  { id: "fr-fc-c1-37", front: "Réfuter une thèse", phonetic: "ray-few-TAY ewn TEHZ", back: "To refute a hypothesis / counter an argument", category: "Levels C1 & C2: Fluency & Mastery", example: "Réfuter une thèse adverse avec des données statistiques rigoureuses." },
  { id: "fr-fc-c1-38", front: "La nuance", phonetic: "lah new-AHNS", back: "Nuance / subtle distinction in meaning", category: "Levels C1 & C2: Fluency & Mastery", example: "Maîtriser une langue au niveau C2 implique de saisir chaque nuance." },
  { id: "fr-fc-c1-39", front: "Avoir voix au chapitre", phonetic: "ah-vwahr vwah oh shah-PEET-ruh", back: "To have a say / entitled to express an opinion", category: "Levels C1 & C2: Fluency & Mastery", example: "Chaque citoyen a le droit d'avoir voix au chapitre." },
  { id: "fr-fc-c1-40", front: "L'apogée", phonetic: "lah-poh-ZHAY", back: "The pinnacle / zenith / climax of an era", category: "Levels C1 & C2: Fluency & Mastery", example: "Cet artiste a atteint l'apogée de sa créativité à Paris." }
